"""Three primary-source reviews with explicit component/assembly distinctions."""
import json
import ledger as L
from review_batch_0001 import evidence
ROWS=[['10.1021/acsnano.8b04148', [['12970052-nn8b04148_si_001.pdf', '12970052', 'All11SIpages captions: supplementalfigures1–10']], 'Wireframe rods include triangular15nm, square13/16/21nm and hexagonal15nm cross-section edge lengths; ligated triangular15nm and reinforced-axial-member square15nm examples are also shown. Salt and staple-breakpoint simulations are distinguished from experimentally imaged constructs. SI provides TEM/cryoTEM and simulation captions, not complete scaffold/staple/native-design sources. Polygonal cross-section alone does not establish square/honeycomb lattice eligibility. Main architecture, exact ligation/reinforcement composition and parent files remain pending; no simulations executed.'], ['10.1021/acs.langmuir.8b02225', [['13020341-la8b02225_si_001.pdf', '13020341', '25-page SI figuresS1–S5 captions and sequence-list header/p3; full sequence tables not audited']], 'Tile DNA templates are seeded with Au nanorods to produce plus,cross,C metal patterns. SI lists pattern-specific staples; blue-font sequences carry protrudingpolyA10capture extensions. FigS5includes a cross variant with a single attachment-sequence row per AuNR. Metal patterns should not be treated as DNAcore outlines without main/map confirmation. Exact shared tile scaffold, base/replacement sets and one-row-versus-other capture geometry remain unverified. Sequence text alone loses blue annotations, so full color/map inspection is required.'], ['10.1021/acscentsci.8b00383', [['13113170-oc8b00383_si_001.pdf', '13113170', 'SIpp2–3preparation methods; mainXMLResults/Fig3 and discussion corroborate actual objects']], 'Implemented nanostructures are TDN13/20/32 made from four oligos,TDN20d formed withA20/T20linkers, and6-helix tube assembled from20component oligos. Primary mainFig3/Results names the same objects; origami citations40/41 compare other uptake studies and larger origami is proposed for future simulations. Same-agent SI-method/main-object audit supports not_origami exclusion from origami-design census. Retain citations as discovery leads; no simulation run or reconstruction performed.'], ['10.1021/acs.langmuir.8b01850', [['13248629-la8b01850_si_001.pdf', '13248629', 'SIcaptions andTable1PDFp9 (printedS8), especially9dsassemblyFig3'], ['13248626-la8b01850_si_002.pdf', '13248626', 'Statistical-analysis supplementFig1caption andTable2factor labels; statistics not independently reproduced']], 'Membrane-binding variants alterTEG-chol attachment atA0–4/B0–4/C0–4 locations. Six strategies:direct,no spacer;proximal;9ss;9ds;18ss;18ds. Table1distinguishes directly modified staples,9ntneighbor-complement and18ntextension/complement; proximal and18ds use same complementary sequence with opposite cholesterol end(3primevs5prime). 9ds pairs modified strand with an extended neighboring staple. Anchor-location combinations andspacer methods are variants, not independently counted cores. SI refers toM13scaffold but base core/native routing/full staples require main/parent. Statistical13-page supplement documents comparison groups, not new designs or source-completeness proof.']]
def main():
 pubs={p['registry_key']:p for p in L.read('publication_reviews')}
 for key,sources,note in ROWS:
  p=pubs[key]
  for name,fid,loc in sources:
   e=evidence(L.ROOT/'assets/sources/acs-expansion-20261104'/name,'https://ndownloader.figshare.com/files/'+fid,loc)
   if e not in p['evidence']:p['evidence'].append(e)
  if key=='10.1021/acscentsci.8b00383':
   e=evidence(L.ROOT/'assets/sources/pre2020-expansion/PMC6202645.xml','https://doi.org/'+key,'Results/Fig3implementedobjects; origami comparison and future-simulation paragraphs')
   if e not in p['evidence']:p['evidence'].append(e)
  p.update(title=p['legacy_record']['publication'],review_stage='design_sources_reviewed',relevance='design_bearing',design_contributions=['uncertain'],catalog_eligibility='unresolved',access='partial',rationale=note,unresolved_questions=['Inspect main and original/native sources; exact scaffold/base/variant compositions and narrow eligibility.','Audit full sequence lists against per-variant maps and assembly recipes.','Enumerate bibliography and follow citations/author histories.'],reviewer='Codex specified SI context inspection',run_id='B0013',date=L.DATE)
  if key=='10.1021/acscentsci.8b00383':p.update(review_stage='fulltext_reviewed',relevance='not_origami',design_contributions=[],catalog_eligibility='excluded',unresolved_questions=['Follow cited origami studies40/41 and bibliography; exact primary source reconciliation pending.'])
  L.upsert('publication_reviews',p,'Record primary component distinctions and unresolved composition')
 b=next(b for b in L.read('batches') if b['batch_id']=='B0013');pubs={p['registry_key']:p for p in L.read('publication_reviews')}
 action='Last4ACS inspected:wireframe rods,metal patterns,nonorigami membrane-attraction study andcholesterolspacers;15of25first-pass screened.'
 if action not in b['completed_actions']:b['completed_actions'].append(action)
 b.update(after_counts=L.counts(),unresolved_keys=[k for k in b['input_keys'] if pubs[k]['review_stage']=='unreviewed'],validation=[L.validate()],next_queue=['Ten rotating2015records startingjbc.r115.638452','Ten rotating2015records','FNANO2010 and all source/discovery followups'])
 if '10.1021/acscentsci.8b00383' not in b['exclusion_audit']['sample']:b['exclusion_audit']['sample'].append('10.1021/acscentsci.8b00383')
 b['exclusion_audit']['reason']='Same-agent SI/main scope audits for BTApolymer and four-strand tetrahedra/20-oligo tube; not an independent reviewer.'
 L.upsert('batches',b,'Save15of25firstpasses,10unreviewed inputs')
 L.atomic(L.HERE/'batch_0013_fifth_audit.json',json.dumps(dict(reviewed_keys=[r[0] for r in ROWS],first_pass_count=15,input_count=25,validation=L.validate(),counts=L.counts()),indent=2)+'\n');print(L.validate())
if __name__=='__main__':main()
